content.query:
let teamFilter = '{Team}';
let userFilter = '{User}';
let modelFilter = '{Model}';
let providerFilter = '{Provider}';
let projectFilter = '{Project}';
customMetrics
| where timestamp {TimeRange}
| extend Team=tostring(customDimensions['Team']), User=tostring(customDimensions['User']), Model=tostring(customDimensions['Model']), Project=tostring(customDimensions['Project'])
| extend Provider=iff(Model startswith 'claude', 'Anthropic', 'OpenAI')
| where teamFilter == 'All' or Team == teamFilter
| where userFilter == 'All' or User == userFilter
| where modelFilter == 'All' or Model == modelFilter
| where providerFilter == 'All' or Provider == providerFilter
| where projectFilter == 'All' or Project == projectFilter
| summarize TotalTokens=toint(sumif(valueSum, name == 'Total Tokens')), InputTokens=toint(sumif(valueSum, name == 'Prompt Tokens')), OutputTokens=toint(sumif(valueSum, name == 'Completion Tokens')), Requests=toint(sumif(valueCount, name == 'Total Tokens'))
